#!/usr/bin/env python3
"""Produce a hash-checked synthesis of existing priority-video evidence."""
import argparse,json,sys
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.memory_token_io import digest,validate_output
p=argparse.ArgumentParser();p.add_argument('--experiments',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();read=lambda f:json.loads(f.read_text())
paths={'memory':'lean_raw_two_window_control_v1/four_sequence_summary_attempt01','spread':'lean_temporal_spread_window_v1/four_sequence_summary_attempt01','prompt':'lean_priority_prompt_quality_v1/audit_attempt01','oracle':'lean_fixed_box_oracle_diagnostic_v1/audit_attempt01','channel':'lean_utility_trained_channel_pilot_v1/audit_attempt02','selection':'lean_utility_trained_channel_pilot_v1/group_selection_attempt01','group_effect':'lean_utility_group_deletion_v1/report_attempt01'}
inputs={};sources={}
for name,relative in paths.items():
 folder=a.experiments/relative;done=read(folder/'completion.json');path=folder/'results.json'
 if not done['passed'] or done['results_sha256']!=digest(path) or done.get('report_sha256')!=digest(folder/'report.md'):raise ValueError(f'{name} result or report changed')
 inputs[name]=read(path);sources[name]={'path':str(path),'results_sha256':digest(path),'report_sha256':digest(folder/'report.md')}
raw=inputs['memory']['sequences'];spread=inputs['spread']['sequences'];prompt={r['sequence']:r for r in inputs['prompt']['results']};oracle=inputs['oracle']['results'];rows=[]
for seq in ('seq8','seq11','seq20','seq23'):
 m=raw[seq];sp=spread[seq];g=prompt[seq]['geometry'];ors=[r for r in oracle if r['sequence']==seq and r['present']]
 if not ors or m['raw_window']['matched_present_count']!=sp['recent']['matched_present_count'] or abs(m['raw_window']['matched_present_dice']-sp['recent']['matched_present_dice'])>1e-12 or m['raw_window']['false_alarms']!=sp['recent']['false_alarms']:raise ValueError('Matched results differ')
 for method in ('baseline','raw_window','fused_window','raw_two'):
  if m[method]['matched_present_count']!=m['baseline']['matched_present_count'] or m[method]['empty_count']!=m['baseline']['empty_count']:raise ValueError('Frame counts differ')
 if m['raw_two']['mean_spatial_keys']!=m['fused_window']['mean_spatial_keys']:raise ValueError('Raw-two/fused key counts differ')
 rows.append({'sequence':seq,'first_detection':prompt[seq]['frame'],'first_label_present':g['present'],'initial_prompt_dice':g['prompt_mask_dice'],'initial_empty_false_alarm':g['empty_prompt_false_alarm'],'matched_present_frames':m['baseline']['matched_present_count'],'empty_frames':m['baseline']['empty_count'],'baseline_dice':m['baseline']['matched_present_dice'],'raw_window_dice':m['raw_window']['matched_present_dice'],'fused_dice':m['fused_window']['matched_present_dice'],'raw_two_dice':m['raw_two']['matched_present_dice'],'spread_dice':sp['spread']['matched_present_dice'],'raw_window_empty_false_alarms':m['raw_window']['false_alarms'],'spread_empty_false_alarms':sp['spread']['false_alarms'],'oracle_sample_count':len(ors),'fixed_box_image_dice':float(np.mean([r['fixed_dice'] for r in ors])),'oracle_box_image_dice':float(np.mean([r['oracle_dice'] for r in ors]))})
out=validate_output(a.output);out.mkdir(parents=True,exist_ok=False);result={'rows':rows,'source_hashes':sources,'runner_sha256':digest(Path(__file__))};(out/'results.json').write_text(json.dumps(result,indent=2)+'\n')
lines=['# Four difficult sequences: decision evidence','','The automatic runs use the same one-shot initialization within each comparison. Present Dice is measured on historical matched target IDs; false alarms cover all labeled-empty frames. Sequence 23 uses the fixed inset-excluded viewport. These are previously inspected videos, not independent test evidence.','','| Sequence | Initial frame / labeled status | Initial mask Dice | Fused-window Dice | Raw-two Dice | Recent-window Dice | Spread-window Dice | Empty FAs recent / spread |','|---|---|---:|---:|---:|---:|---:|---:|']
for r in rows:
 init=f"{r['first_detection']} / "+('present' if r['first_label_present'] else 'empty');md='—' if r['initial_prompt_dice'] is None else f"{r['initial_prompt_dice']:.3f}";lines.append(f"| {r['sequence']} | {init} | {md} | {r['fused_dice']:.3f} | {r['raw_two_dice']:.3f} | {r['raw_window_dice']:.3f} | {r['spread_dice']:.3f} | {r['raw_window_empty_false_alarms']} / {r['spread_empty_false_alarms']} ({r['empty_frames']}) |")
lines+=['','Fused and raw-two have equal spatial and pointer read counts, but their memory contents and trajectories differ. Recent and spread have matched represented-token budgets and read counts, but different histories and predictions; older frames reuse the oldest learned temporal slot. The budget is not total RAM or a speed measurement. Historical native and Lean baselines were initialized with ground-truth masks, so they are descriptive unequal-prompt references, not controls for these automatic runs.','','The automatic initialization on seq20 and seq23 was nonempty on a labeled-empty frame. Seq11 starts on a labeled-present frame with an overextended prompt (Dice about 0.686); later predictions retain substantial background. Seq8 has a strong initial prompt but still suffers later drift. Empty annotations may be incomplete, and these observations do not prove the causes of later failures.','','On five retrospectively selected target frames per video, fixed initial boxes versus explicit label-derived oracle boxes were evaluated with a SAM2 image predictor, not video propagation:']
for r in rows:lines.append(f"- {r['sequence']}: {r['oracle_sample_count']} present frames, fixed-box Dice {r['fixed_box_image_dice']:.3f}; oracle-box Dice {r['oracle_box_image_dice']:.3f}.")
lines+=['','The oracle uses ground truth and is not deployable or a guaranteed upper bound. Without redetection or a new confidence gate, an incorrect one-shot location remains a material limitation. The utility-trained channel gate did not consistently beat uniform or shuffled controls on five present evaluation reads; the equal-key selected-mask effects were tiny and the one eligible empty read had a false alarm for every method. Do not promote that gate to propagation on the current evidence.','','Same-read raw-versus-fused exchanges on selected seq23 frames produced at most a small measured Dice change and cannot by themselves explain full-trajectory differences. Future candidates need matched automatic prompts, budgets and read counts, and a demonstrated benefit beyond RGB, shuffled, usage and distributed controls before full-video testing. See source hashes and paths in results.json.']
(out/'report.md').write_text('\n'.join(lines)+'\n');(out/'completion.json').write_text(json.dumps({'passed':True,'results_sha256':digest(out/'results.json'),'report_sha256':digest(out/'report.md')},indent=2)+'\n');print('\n'.join(lines))
